#include <iostream>
#include <string>
using namespace std;

int main() {
    string S;
    cin >> S;
    unsigned Q;
    cin >> Q;

    unsigned long N = size(S);

    for (unsigned i = 0; i < Q; ++i) {
        unsigned long K;
        cin >> K;
        --K;
        // 何周期目の何文字目かを求める
        unsigned long repeat = K / N, offset = K % N;
        // 周期の情報から大文字小文字が入れ替わっているかを求める
        unsigned long parity = repeat;
        parity ^= parity >> 1;
        parity ^= parity >> 2;
        parity &= 0x1111111111111111UL;
        parity = 1 & (parity * 0x1111111111111111UL >> 60);

        // parity が 1 なら大文字小文字を入れ替える
        putchar(S[offset] ^ 32 * parity);
        putchar(32);
    }

    return 0;
}

S = input()
Q = int(input())
K = map(int, input().split())


def f(k, l):
    if l == 0:
        return S[k - 1]
    h = len(S) << (l - 1)
    if k <= h:
        return f(k, l - 1)
    return chr(ord(f(k - h, l - 1)) ^ 32)


for k in K:
    print(f(k, 60), end=" ")
